WITH item_carrier_metrics AS ( SELECT i.inv_item_sk AS inv_item_sk, sm.sm_carrier AS sm_carrier, SUM(i.inv_quantity_on_hand) AS total_inventory_qty, SUM(wr.wr_return_quantity) AS total_return_qty, SUM(wr.wr_return_amt_inc_tax) AS total_return_amt, SUM(wr.wr_net_loss) AS total_net_loss, AVG(wr.wr_return_amt_inc_tax) AS avg_return_amt, COUNT(DISTINCT wr.wr_order_number) AS distinct_orders_returned FROM inventory i JOIN web_returns wr ON i.inv_item_sk = wr.wr_item_sk AND i.inv_date_sk = wr.wr_returned_date_sk JOIN ship_mode sm ON sm.sm_ship_mode_sk = i.inv_warehouse_sk WHERE i.inv_quantity_on_hand > 200 AND sm.sm_carrier IN ('UPS', 'FEDEX') GROUP BY i.inv_item_sk, sm.sm_carrier HAVING SUM(wr.wr_return_quantity) > 0 ) SELECT im.inv_item_sk, im.sm_carrier, im.total_inventory_qty, im.total_return_qty, im.total_return_amt, im.total_net_loss, im.avg_return_amt, im.distinct_orders_returned, RANK() OVER (PARTITION BY im.sm_carrier ORDER BY im.total_net_loss DESC) AS carrier_net_loss_rank FROM item_carrier_metrics im ORDER BY im.total_net_loss DESC LIMIT 100
